using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BattleActionToRandomTargetOmenLogic", menuName = "Data/Battle/Omens System/Omen Logic/BattleActionToRandomTarget Omen Logic")]
public class BattleActionToRandomTargetOmenLogic : OmenLogic
{
	[Header("Units")]
	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	public override void ActivateOmen(BattleAction battleAction, int actionValue, GameObject target, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		GameObject gameObject = null;
		gameObject = currentActiveUnits.GetCurrentActiveUnits().PickRandom();
		battleAction.CastTargetAmount(gameObject, actionValue, source);
	}
}
